    public static (int Dist, long Enqueued) Shortest(int n) {
        var seen = new bool[n, n];
        var q = new Queue<(int R, int C, int D)>();
        q.Enqueue((0, 0, 0));
        long enq = 1;
        while (q.Count > 0) {
            var (r, c, d) = q.Dequeue();
            if (seen[r, c]) continue;
            seen[r, c] = true;
