## The idea

Each word is a node; two words are connected if they differ in exactly one letter. The fewest transformations is the **shortest path**, so use breadth-first search. To find neighbours fast, put each word into "buckets" by pattern: APE belongs to *PE, A*E and AP*. Words in the same bucket differ only at the starred letter. Adding a word later only means adding it to its buckets. For speed, search from both ends at once (bidirectional BFS).

## Step by step

1. For every dictionary word and every position, replace that letter with * and add the word to that pattern's list.
2. Query: same word → 0; different lengths or end not in the dictionary → −1.
3. BFS from start, one level at a time. The neighbours of a word are all words in its patterns' lists. When we reach the end word, return the level number.
4. AddWord: add the word to its patterns (no rebuild).
5. Bidirectional: keep a frontier for each side; always expand the smaller one; stop when a word is already seen by the other side.

## Worked example

**Input:** dictionary APE APT OPT OAT MAT MAN …; APE → MAN

| Step | What happens |
|---|---|
| level 1 | APE → APT (A P *) and OPE (* P E) |
| level 2 | APT → OPT |
| level 3 | OPT → OAT |
| level 4 | OAT → MAT |
| level 5 | MAT → MAN = target |

**Result:** 5 transformations

## Cost

Building: O(N · L²) for N words of length L (L patterns, each L characters). Each BFS: O(N · L²) worst case. Bidirectional BFS usually touches far fewer words. Memory O(N · L).

## The code (C#, compiled and tested against every part of the question)

```csharp
public class WordTransformer {
    private readonly HashSet<string> _words = new HashSet<string>();
    // pattern like "A*E" -> every word that matches it
    private readonly Dictionary<string, List<string>> _buckets = new Dictionary<string, List<string>>();

    public WordTransformer(IEnumerable<string> dictionary) {
        foreach (string word in dictionary) AddWord(word);
    }

    // New words just join their buckets — nothing else is rebuilt.
    public void AddWord(string word) {
        if (_words.Contains(word)) return;
        _words.Add(word);
        foreach (string pattern in Patterns(word)) {
            if (!_buckets.ContainsKey(pattern)) _buckets[pattern] = new List<string>();
            _buckets[pattern].Add(word);
        }
    }

    // "APE" -> "*PE", "A*E", "AP*"
    private static List<string> Patterns(string word) {
        List<string> result = new List<string>();
        char[] letters = word.ToCharArray();
        for (int i = 0; i < letters.Length; i++) {
            char keep = letters[i];
            letters[i] = '*';
            result.Add(new string(letters));
            letters[i] = keep;
        }
        return result;
    }

    private List<string> Neighbours(string word) {
        List<string> result = new List<string>();
        foreach (string pattern in Patterns(word)) {
            List<string> bucket;
            if (!_buckets.TryGetValue(pattern, out bucket)) continue;
            foreach (string other in bucket) {
                if (other != word) result.Add(other);
            }
        }
        return result;
    }

    // Number of single-letter changes (edges). 0 for the same word, -1 if impossible.
    public int MinTransformations(string start, string end) {
        if (start == null || end == null || start.Length != end.Length) return -1;
        if (start == end) return 0;
        if (!_words.Contains(end)) return -1;

        HashSet<string> seen = new HashSet<string> { start };
        Queue<string> queue = new Queue<string>();
        queue.Enqueue(start);
        int steps = 0;
        while (queue.Count > 0) {
            steps++;
            int levelSize = queue.Count;
            for (int i = 0; i < levelSize; i++) {
                string current = queue.Dequeue();
                foreach (string next in Neighbours(current)) {
                    if (next == end) return steps;
                    if (!seen.Contains(next)) {
                        seen.Add(next);
                        queue.Enqueue(next);
                    }
                }
            }
        }
        return -1;
    }

    // Same answer, searching from both ends and always growing the smaller side.
    public int MinTransformationsBidirectional(string start, string end) {
        if (start == null || end == null || start.Length != end.Length) return -1;
        if (start == end) return 0;
        if (!_words.Contains(end)) return -1;

        HashSet<string> frontA = new HashSet<string> { start }, seenA = new HashSet<string> { start };
        HashSet<string> frontB = new HashSet<string> { end }, seenB = new HashSet<string> { end };
        int steps = 0;
        while (frontA.Count > 0 && frontB.Count > 0) {
            steps++;
            bool met;
            if (frontA.Count <= frontB.Count) frontA = Expand(frontA, seenA, seenB, out met);
            else frontB = Expand(frontB, seenB, seenA, out met);
            if (met) return steps;
        }
        return -1;
    }

    private HashSet<string> Expand(HashSet<string> frontier, HashSet<string> mySeen, HashSet<string> otherSeen, out bool met) {
        HashSet<string> next = new HashSet<string>();
        foreach (string word in frontier) {
            foreach (string neighbour in Neighbours(word)) {
                if (otherSeen.Contains(neighbour)) { met = true; return next; }
                if (!mySeen.Contains(neighbour)) {
                    mySeen.Add(neighbour);
                    next.Add(neighbour);
                }
            }
        }
        met = false;
        return next;
    }
}
